			/**
			 * 데이터 저장 서브미션 호출
			 */
			function doSave(untTaskwkSeCd, caseMngNo, caseMngOdrNo) {

			    var vnSeltTabId = util.Tab.getSelectedId(app, "fldCaseTrmn");
			    var embapp4 = app.lookup("embapp4").getEmbeddedAppInstance();
			    var drmgsTrmn = false;  // 학업중단숙려제
			    var resultEndYmd = "";
			    var dscsnResult = "";
			    var endAftrSprt = "";
			    var endAftrDtl  = "";
			    if(untTaskwkSeCd == "U03"){ // 학교밖
			        resultEndYmd = embapp4.lookup("dsOutcomeDetail").getValue(0, "RESULT_END_YMD");
			        dscsnResult = embapp4.lookup("dsOutcomeDetail").getValue(0, "SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD");
			        endAftrSprt = embapp4.lookup("dsOutcomeDetail").getValue(0, "SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD");
			        endAftrDtl  = embapp4.lookup("dsOutcomeDetail").getValue(0, "SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_DTL_CN");
			        if(!ValueUtil.isNull(resultEndYmd) || !ValueUtil.isNull(dscsnResult) ||
			           !ValueUtil.isNull(endAftrSprt) || !ValueUtil.isNull(endAftrDtl)){
			            if(ValueUtil.isNull(resultEndYmd)){
			                util.Msg.alert(app, "학업중단숙려제의 결과종료일자를 입력해주세요.");
			                return false;
			            }
			            if(ValueUtil.isNull(dscsnResult)){
			                util.Msg.alert(app, "학업중단숙려제의 상담결과를 선택해주세요.");
			                return false;    
			            }
			            if(ValueUtil.isNull(endAftrSprt)){
			                util.Msg.alert(app, "학업중단숙려제의 종료이후지원을 선택해주세요.");
			                return false;    
			            }
			            drmgsTrmn = true;   // 학업중단숙려제 데이터 있음
			        }    
			    }
			    if(drmgsTrmn){
			        util.Msg.confirm(app, "학업중단숙려제를 저장 하시겠습니까?\n확인을 선택하시면 학업중단숙려제만 저장 됩니다.\n취소를 선택하시면 종결상세정보도 저장 됩니다.", null, function(){
			            var submission  = app.lookup("subTrmnSave");
			            submission.action = "/isry/drmgs/cases/drmgsCaseTrmnDetailSave.do";
			            util.DataSet.setValue(app, "dsCaseTrmn", 0, "CASE_MNG_NO"   , caseMngNo);    //사례관리번호
			            util.DataSet.setValue(app, "dsCaseTrmn", 0, "CASE_MNG_ODRNO", caseMngOdrNo); //사례관리차수
			            if(vsAppId != null) {
			                //업무영역 출력화면에서 데이터셋 추출하여 서브미션에 Add
			                vcEmbDefInfo.getEmbeddedAppInstance().getAllDataControls().forEach(function(ctrl) {
			                    if(ctrl.type == "dataset") {
			                        submission.addRequestData(ctrl, "all");
			                    }
			                });
			            }
			            util.Submit.send(app, "subTrmnSave", function(pbSuccess) {
			                if (pbSuccess) {
			                    util.Msg.notify(app, "INF-M000", "학업중단숙려제가 저장 되었습니다.");
			                    if(app.getHostAppInstance().hasAppMethod("setStepNocs")) {
			                        app.getHostAppInstance().callAppMethod("setStepNocs");                            
			                    }
			                    if(app.getHostAppInstance().hasAppMethod("setDtlCrud")) {
			                        app.getHostAppInstance().callAppMethod("setDtlCrud", "READ");                            
			                    }
			                }
			            });
			        }, function(){
			            // 취소 선택 시
			            mainTrmnSave(vnSeltTabId, untTaskwkSeCd, caseMngNo, caseMngOdrNo);    
			        });
			    } else {
			        mainTrmnSave(vnSeltTabId, untTaskwkSeCd, caseMngNo, caseMngOdrNo);
			    }
			    
			}
			exports.doSave = doSave;

			function mainTrmnSave(vnSeltTabId, untTaskwkSeCd, caseMngNo, caseMngOdrNo){
			    //종결신청
			    if(vnSeltTabId == "1") {
			        util.DataSet.copyToDataSet(app, "dsCaseTrmnAply", "dsCaseTrmn");
			        if (!util.validate(app, "grp6")) return false;

			        // 미지원/삭제 코드 선택 확인
			        var bFlag = true;
			        var sMsg  = "";

			        var comList = AppUtil.getComponentList(app, "grpCaseTrmnAply", "combobox");
			        for(var i=0; i<comList.length; i++) {
			            var comObj = comList[i];

			            var sText       = comObj.text;
			            var sFiledLabel = comObj.fieldLabel;

			            if(comObj.visible && comObj.enabled && !comObj.readonly) {
			                if(sText.indexOf('[삭제]') > -1 || sText.indexOf('[미지원]') > -1) {
			                    bFlag = false;

			                    if(ValueUtil.isNull(sMsg)) {
			                        sMsg = "삭제 또는 미지원 코드가 선택되어 있습니다.\n" + sFiledLabel + "을(를) 확인해 주세요.";
			                    } else {
			                        sMsg = sMsg + "\n" + sFiledLabel + "을(를) 확인해 주세요.";
			                    }
			                }
			            }
			        }

			        if(!bFlag) {
			            util.Msg.alert(app, sMsg);
			            return false;
			        }
			    }
			    //종결처리
			    else if(vnSeltTabId == "2") {
			        util.DataSet.copyToDataSet(app, "dsCaseTrmnSrng", "dsCaseTrmn");
			        if (!util.validate(app, "grp7")) return false;

			        var sTrmnSrngResultSeCd = util.DataSet.getValue(app, "dsCaseTrmn", 0, "TRMN_SRNG_RESULT_SE_CD");
			        var sCaseTrmnYmd        = util.DataSet.getValue(app, "dsCaseTrmn", 0, "CASE_TRMN_YMD");

			        if(sTrmnSrngResultSeCd == "02") {
			            if(cpr.utils.Util.toNumber(sCaseBgngYmd) > cpr.utils.Util.toNumber(sCaseTrmnYmd)) {
			                util.Msg.alert(app, "사례종결일자가 사례시작일자보다 빠를수 없습니다.");
			                app.lookup("dti6").focus();
			                return false;
			            } else {                
			                var bCheckVal = true;

			                if(!ValueUtil.isNull(sDdlnCrtrYmd)) {
			                    //1.마감기준일자 vs 당일 비교
			                    if(sDdlnCrtrYmd > vsToday) {
			                        if(sCaseTrmnYmd.substring(0,6) < sDdlnYm) {
			                            bCheckVal = false;
			                        }
			                    } else {
			                        if(sCaseTrmnYmd.substring(0,6) <= sDdlnYm) {
			                            bCheckVal = false;
			                        }
			                    }
			                    if(!bCheckVal) {
			                        util.Msg.alert(app, "마감년월[" + sDdlnYm + "]의 마감기준일자[" + sDdlnCrtrYmd + "]를 확인 후 사례종결일자를 설정해 주시기 바랍니다.");
			                        return false;
			                    }
			                }
			            }
			        }
			    }

			//    if (!util.validate(app, "grpData")) return false;

			    //업무별 화면 내부로직은 스크립트에서 자체처리 하시면 됩니다.
			    //1.업무영역 출력화면 유효성체크
			    if(vcEmbDefInfo.hasAppMethod("chkVal")){
			        if(!vcEmbDefInfo.callAppMethod("chkVal", "Y")) return false;
			    }

			    var confirmMsg = "";
			    //사후관리여부 체크
			    var sAftfctMngYn = app.lookup("dsCaseTrmn").getValue(0, "AFTFCT_MNG_YN");
			    var trmnSrngResultSeCd = app.lookup("dsCaseTrmnSrng").getValue(0, "TRMN_SRNG_RESULT_SE_CD"); // 승인여부
			    var stts   = util.DataSet.getValue(app, "dsCaseTrmnList", 0, "CASE_PRGRS_STTS_SE_CD");
			    if(stts == "12" && trmnSrngResultSeCd == "03"){ // 종결신청 && 미승인
			        confirmMsg = "미승인 처리 하시겠습니까?";
			    } else if(trmnSrngResultSeCd == "02"){ // 승인
			        if(sAftfctMngYn == "N"){
			            confirmMsg = "※ 사후관리 미선택시 대상자의 사례관리가 종결 됩니다.\n";    
			        }
			        if(vnSeltTabId == "2") { // 종결 처리
			            if(untTaskwk == "U04"){ // 청소년쉼터
			                confirmMsg += "※ 자립지원수당 대상여부 확인 하셨나요?\n";
			                confirmMsg += "자립지원수당 대상여부는 업무지원-증명서발급-신규발급\n";
			                confirmMsg += "-청소년쉼터 입소기간 확인서(자립지원수당 신청용)를\n";
			                confirmMsg += "이용하여 확인하실 수 있습니다.\n";
			                confirmMsg += "대상인 경우 즉시 신청하시기 바랍니다.\n";   
			            }
			            confirmMsg += "종결처리 하시겠습니까?";
			        }
			    }
			    
			    
			    if(confirmMsg != ""){
			        util.Msg.confirm(app, confirmMsg, null,
			            function() {    //저장진행
			                confirmTrmmCallback(vnSeltTabId, caseMngNo, caseMngOdrNo);
			            }, // 저장실행
			            function() {    //저장취소
			                return false;
			            }, "저장확인"
			        );
			    } else {
			        confirmTrmmCallback(vnSeltTabId, caseMngNo, caseMngOdrNo);
			    }
			}

			function confirmTrmmCallback(vnSeltTabId, caseMngNo, caseMngOdrNo){
			    if(vnSeltTabId == "1") {
			        //첨부파일 저장 실행
			        var objMultifileupload = app.lookup("cmnMultifileupload");//첨부파일
			        objMultifileupload.send(function(){
			            var sAtfino = "";
			            if(objMultifileupload.getFileList().length > 0) {
			                sAtfino = app.lookup("dsCaseTrmnAply").getValue(0, "ATFINO");
			                app.lookup("dsCaseTrmn").setValue(0, "ATFINO", sAtfino);
			            }
			            callSave(untTaskwk, caseMngNo, caseMngOdrNo, vnSeltTabId);
			        });
			    } else {
			        callSave(untTaskwk, caseMngNo, caseMngOdrNo, vnSeltTabId);
			    }
			    return true;
			}

