			function callSave(untTaskwkSeCd, caseMngNo, caseMngOdrNo, vnSeltTabId) {

			    var submission  = app.lookup("subTrmnSave");

			    //단위업무_ACTION_URL 조회
			    util.DataMap.setValue(app, "dmUrlParam", "CMMNS_CD"    , "UNT_TASKWK_ACTION_URL");
			    util.DataMap.setValue(app, "dmUrlParam", "TASKWK_SE_CD", untTaskwkSeCd);
			    util.DataMap.setValue(app, "dmUrlParam", "STEP"        , "05");

			    util.Submit.send(app, "subUrl", function(pbSuccess) {
			        if (pbSuccess) {
			            var sPageUrl = null;

			            for(var i=0; i< util.DataSet.getRowCount(app, "dsUrlList"); i++){
			                sPageUrl = util.DataSet.getValue(app, "dsUrlList", i, "PAGE_URL");
			            }

			            if (!(ValueUtil.isNull(sPageUrl) || sPageUrl == 0)){
			                submission.action = sPageUrl;
			            } else {
			                submission.action = "/isry/itgcm/casemng/caseunity/processCaseTrmnDetail.do";
			            }

			            util.DataSet.setValue(app, "dsCaseTrmn", 0, "CASE_MNG_NO"   , caseMngNo);    //사례관리번호
			            util.DataSet.setValue(app, "dsCaseTrmn", 0, "CASE_MNG_ODRNO", caseMngOdrNo); //사례관리차수

			            if(vsAppId != null) {
			                //업무영역 출력화면에서 데이터셋 추출하여 서브미션에 Add
			                vcEmbDefInfo.getEmbeddedAppInstance().getAllDataControls().forEach(function(ctrl) {
			                    if(ctrl.type == "dataset") {
			                        submission.addRequestData(ctrl, "all");
			                    }
			                });
			            }
			            var readOnly = "";
			            if(vnSeltTabId == 2){
			                readOnly = "READ_ONLY";
			            } else {
			                readOnly = "READ";
			            }
			            util.Submit.send(app, "subTrmnSave", function(pbSuccess) {
			                if (pbSuccess) {
			                    if(!(ValueUtil.isNull(sPageUrl) || sPageUrl == 0)) {
			                        submission.action = "/isry/itgcm/casemng/caseunity/processCaseTrmnDetail.do";

			                        util.Submit.send(app, "subTrmnSave", function(pbSuccess) {
			                            if(pbSuccess) {
			                                util.Msg.alert(app, "저장 되었습니다.");
			                                doList("save");

			                                if(app.getHostAppInstance().hasAppMethod("setStepNocs")) {
			                                    app.getHostAppInstance().callAppMethod("setStepNocs");                            
			                                }
			                                if(app.getHostAppInstance().hasAppMethod("setDtlCrud")) {
			                                    app.getHostAppInstance().callAppMethod("setDtlCrud", readOnly);                            
			                                }
			                            } else {
			                                util.Msg.alert(app, "업무공통 영역 저장 실패.");
			                            }
			                        });
			                    } else {
			                        util.Msg.alert(app, "저장 되었습니다.");
			                        doList("save");

			                        if(app.getHostAppInstance().hasAppMethod("setStepNocs")) {
			                            app.getHostAppInstance().callAppMethod("setStepNocs");                            
			                        }
			                        if(app.getHostAppInstance().hasAppMethod("setDtlCrud")) {
			                            app.getHostAppInstance().callAppMethod("setDtlCrud", readOnly);                            
			                        }
			                    }
			                } else {
			                    util.Msg.alert(app, "단위업무 영역 저장 실패.");
			                }
			            });
			        }
			    });
			}

